            (balAfterDeposit == 0 && balAfterWithdraw == 0 && selfAfter == selfBefore + amount && contractAfter == contractBefore) ||
            (balAfterDeposit > 0 && balAfterWithdraw == 0 && selfAfter == selfBefore + balAfterDeposit && contractAfter == contractBefore + amount - balAfterDeposit)
        );
    }
    receive() external payable {}
}

