contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}();

        uint recordedBeforeWithdraw = c.getBalance(address(this));
        uint contractBalanceBeforeWithdraw = address(c).balance;
        uint testBalanceBeforeWithdraw = address(this).balance;

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.getBalance(address(this)) == recordedBeforeWithdraw);
            assert(address(c).balance == contractBalanceBeforeWithdraw);
        } else {
            assert(c.getBalance(address(this)) == 0);
            assert(address(c).balance == contractBalanceBeforeWithdraw - recordedBeforeWithdraw);
            assert(address(this).balance == testBalanceBeforeWithdraw + recordedBeforeWithdraw);
        }
    }

    receive() external payable {}
}
